// Loot of a won fight, generated by the game from the creatures defeated
// (never by the AI): coins, the weapons and armor they carried and, now and
// then, a Potion of Healing. Duncan only narrates the result.
//
// Rules (chosen to stay modest; see the pull request):
//  - Only for a victory, and only from creatures that were killed or
//    surrendered (the ones that fled keep their things).
//  - Coins: only creatures that carry treasure (humanoids, fey, giants, fiends,
//    dragons, aberrations, celestials; undead half the time). Per creature, by
//    CR, after the individual treasure of the 2024 rules: CR 0-1/8 3d6 pp;
//    1/4-4 3d6 po; 5-10 2d8×10 po; 11-16 2d10×100 po; 17+ 2d8×1.000 po.
//  - Weapons: the SRD weapons that humanoid-sized carriers fought with; at most
//    two per fight, each with a 50 % chance. Giants' weapons are too big.
//  - Armor: the armor some humanoids wear (see CARRIED_ARMOR); at most one
//    piece per fight, with a 25 % chance.
//  - Potions: one roll per fight on the highest CR among the carriers:
//    CR ≤ 4: 15 % Potion of Healing; 5-10: 25 % healing or greater; 11-16: 30 %
//    greater or superior; 17+: 35 % superior, or supreme 1 time in 5.

import { WEAPON_NAME_HINTS } from '../data/weapons';
import { makeItem, roundCoins, formatCoins } from './items';

const CARRIER_TYPES = ['humanoide', 'feérico', 'gigante', 'infernal', 'dragón', 'aberración', 'celestial'];
const WEAPON_CARRIER_TYPES = ['humanoide', 'feérico', 'muerto viviente', 'infernal'];
export const WEAPON_DROP_CHANCE = 0.5;
export const MAX_WEAPONS = 2;
export const ARMOR_DROP_CHANCE = 0.25;

/** Armor worn by some creatures of the bestiary (their stat block AC comes from it). */
export const CARRIED_ARMOR = {
  bandit: 'leather', cultist: 'leather', guard: 'chainShirt', warriorInfantry: 'chainShirt',
  goblinWarrior: 'leather', goblinBoss: 'chainShirt', hobgoblinWarrior: 'chainMail', hobgoblinCaptain: 'halfPlate',
  scout: 'leather', spy: 'leather', pirate: 'leather', priestAcolyte: 'chainShirt', priest: 'chainShirt',
  banditCaptain: 'studdedLeather', berserker: 'hide', cultistFanatic: 'leather', knight: 'plate',
  warriorVeteran: 'splint', guardCaptain: 'breastplate', gladiator: 'studdedLeather', assassin: 'studdedLeather',
  bugbearWarrior: 'hide', gnollWarrior: 'hide'
};
/** Creatures that also carry a shield. */
const CARRIED_SHIELD = ['guard', 'goblinWarrior', 'goblinBoss', 'hobgoblinWarrior', 'guardCaptain', 'gladiator', 'priest'];

const roll = (rng, count, sides) => Array.from({ length: count }, () => 1 + Math.floor(rng() * sides)).reduce((a, b) => a + b, 0);

/** Coins one creature carries (gold pieces, may have silver). */
export function coinsFor(cr, rng) {
  if (cr <= 0.125) return roundCoins(roll(rng, 3, 6) / 10);
  if (cr <= 4) return roll(rng, 3, 6);
  if (cr <= 10) return roll(rng, 2, 8) * 10;
  if (cr <= 16) return roll(rng, 2, 10) * 100;
  return roll(rng, 2, 8) * 1000;
}

const carriesTreasure = (enemy, rng) => CARRIER_TYPES.includes(enemy.type) || (enemy.type === 'muerto viviente' && rng() < 0.5);

/** The SRD weapon an attack of a stat block is ("Cimitarra" -> scimitar), or null for claws, spells... */
export function weaponOfAction(action) {
  if (!action || (action.kind !== 'melee' && action.kind !== 'ranged')) return null;
  const name = String(action.name || '').toLowerCase();
  const hint = WEAPON_NAME_HINTS.find(([words]) => name.includes(words));
  return hint ? hint[1] : null;
}

function potionRoll(maxCr, rng) {
  if (maxCr == null) return null;
  const r = rng();
  if (maxCr <= 4) return r < 0.15 ? 'healing' : null;
  if (maxCr <= 10) return r < 0.25 ? (rng() < 0.5 ? 'healing' : 'greaterHealing') : null;
  if (maxCr <= 16) return r < 0.3 ? (rng() < 0.6 ? 'greaterHealing' : 'superiorHealing') : null;
  return r < 0.35 ? (rng() < 0.2 ? 'supremeHealing' : 'superiorHealing') : null;
}

/**
 * Loot of a finished encounter.
 * @returns {{ coins: number, items: object[] }}  items are new inventory items
 */
export function generateLoot(encounter, rng = Math.random) {
  if (!encounter || encounter.status !== 'victory') return { coins: 0, items: [] };
  const defeated = encounter.enemies.filter(e => e.status === 'dead' || e.status === 'surrendered');
  const carriers = defeated.filter(e => carriesTreasure(e, rng));

  const coins = roundCoins(carriers.reduce((sum, e) => sum + coinsFor(Number(e.cr) || 0, rng) * (e.elite ? 2 : 1), 0));
  const items = [];

  // Weapons they fought with (one candidate per creature: its first SRD weapon)
  const weaponIds = defeated
    .filter(e => WEAPON_CARRIER_TYPES.includes(e.type))
    .map(e => (e.actions || []).map(weaponOfAction).find(Boolean))
    .filter(Boolean);
  weaponIds.forEach(id => {
    if (items.length < MAX_WEAPONS && rng() < WEAPON_DROP_CHANCE) items.push(makeItem(`weapon:${id}`));
  });

  // At most one piece of armor (or a shield)
  const armors = defeated.flatMap(e => [
    ...(CARRIED_ARMOR[e.monsterId] ? [CARRIED_ARMOR[e.monsterId]] : []),
    ...(CARRIED_SHIELD.includes(e.monsterId) ? ['shield'] : [])
  ]);
  if (armors.length && rng() < ARMOR_DROP_CHANCE) items.push(makeItem(`armor:${armors[Math.floor(rng() * armors.length)]}`));

  const maxCr = carriers.length ? Math.max(...carriers.map(e => Number(e.cr) || 0)) : null;
  const potion = potionRoll(maxCr, rng);
  if (potion) items.push(makeItem(`potion:${potion}`));

  return { coins, items: items.filter(Boolean) };
}

/** "12 po, Cimitarra y Poción de curación" (or "nada de valor"). */
export function describeLoot(loot) {
  const parts = [...(loot?.coins > 0 ? [formatCoins(loot.coins)] : []), ...(loot?.items || []).map(i => i.name)];
  if (!parts.length) return 'nada de valor';
  return parts.length === 1 ? parts[0] : `${parts.slice(0, -1).join(', ')} y ${parts.at(-1)}`;
}
